Потоковый конвейер:

import { pipeline } from 'node:stream/promises';
import { createReadStream } from 'node:fs';
import zlib from 'node:zlib';
import { Transform } from 'node:stream';

class ParseRedactStringify extends Transform {
  constructor() { super({ readableObjectMode: false, writableObjectMode: false }); this.tail=''; }
  _transform(chunk, _enc, cb) {
    const lines = (this.tail + chunk).split('\n');
    this.tail = lines.pop();
    try {
      for (const line of lines) {
        if (!line) continue;
        const rec = JSON.parse(line);
        delete rec.ssn;                 // редактируем до того, как покинет машину
        this.push(JSON.stringify(rec) + '\n'); // пуш на запись — без буферизации
      }
      cb();
    } catch (err) { cb(err); }          // битый JSON прерывает весь pipeline
  }
  _flush(cb) {
    try { if (this.tail) { const r = JSON.parse(this.tail); delete r.ssn; this.push(JSON.stringify(r)+'\n'); } cb(); }
    catch (err) { cb(err); }
  }
}

async function run(srcPath, key, storage) {
  await pipeline(
    createReadStream(srcPath),       // Readable (быстрый, локальный диск)
    new ParseRedactStringify(),      // Transform (потоковый map, пуш на запись)
    zlib.createGzip(),               // Transform (сжатие)
    storage.createUploadStream(key), // Writable (медленный сетевой приёмник)
  );
  // резолвится ТОЛЬКО когда последний байт слит в хранилище; реджектится, если ЛЮБОЙ этап упал
}

Почему верно: (1) pipeline проводит backpressure через все четыре этапа, так что медленная загрузка придушивает чтение с диска — память остаётся ограниченной около нескольких highWaterMark (~3×16КБ), а не размера файла. (2) Ошибка где угодно — ошибка чтения fs, JSON.parse на битой строке через cb(err), ошибка gzip или ошибка загрузки — доходит до единственного await, и pipeline разрушает каждый поток (fd чтения, transform, gzip, сокет загрузки), так что ничто не течёт. (3) Transform пушит на запись и обрабатывает только хвостовую частичную строку в _flush; он никогда не накапливает весь файл, что и есть OOM-ловушка. (4) Успех определён как резолв pipeline (последний байт слит), так что упавшая загрузка реджектится и никогда не рапортуется завершённым экспортом — без частичного-но-успеха. Если нужен явный abort (таймаут/отмена), передай AbortSignal в pipeline.
